def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_count += 1
            if opp.get('budget', 0) >= budget:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    max_prev = max(prev_bids) if prev_bids else DAILY_SALARY * 0.7
    sorted_prev = sorted(prev_bids) if prev_bids else [DAILY_SALARY * 0.7]
    second_prev = sorted_prev[-2] if len(sorted_prev) >= 2 else sorted_prev[-1]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else DAILY_SALARY * 0.7

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgent = hp <= 2 or no_water_days >= 2
    fragile = hp <= 4 or no_water_days >= 1

    if urgent:
        bid = max(max_prev + 3.0, DAILY_SALARY * (0.95 + 0.15 * scarcity))
    elif fragile:
        bid = max(second_prev + 2.0, avg_prev * (0.9 + 0.15 * scarcity), DAILY_SALARY * (0.72 + 0.18 * scarcity))
    else:
        if max_prev >= DAILY_SALARY * 1.3:
            bid = DAILY_SALARY * (0.28 + 0.18 * scarcity)
        elif max_prev >= DAILY_SALARY * 1.0:
            bid = DAILY_SALARY * (0.4 + 0.2 * scarcity)
        else:
            bid = max(DAILY_SALARY * (0.48 + 0.18 * scarcity), second_prev + 1.0)

    if desperate_count >= 2:
        bid += 6.0 + 6.0 * scarcity
    elif desperate_count == 1:
        bid += 3.0 * scarcity

    if rich_count >= 2 and not urgent:
        bid -= 2.0

    if day <= 2 and not urgent:
        bid *= 0.92
    if day >= 8 and fragile:
        bid *= 1.08

    reserve_floor = 0.0
    if hp > 4 and day < 8:
        reserve_floor = DAILY_SALARY * 2.0
    max_affordable = max(0.0, budget - reserve_floor)

    if urgent:
        final_bid = min(budget, max(bid, DAILY_SALARY * 0.9))
    else:
        if max_affordable > 0:
            final_bid = min(max_affordable, bid)
        else:
            final_bid = min(budget, DAILY_SALARY * 0.35)

    if final_bid < 0:
        final_bid = 0.0
    if final_bid > budget:
        final_bid = budget

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            pass

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    top_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units we can plausibly buy given supply.
    # Bids compete; we use supply to scale risk: higher supply -> can bid less.
    supply_scale = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_scale = max(0.0, min(1.0, supply_scale))

    # Survival urgency: if we have gone several days without water or low HP, bid more.
    urgency = 0
    if hp <= 2.0:
        urgency = 3
    elif hp <= 4.0:
        urgency = 2
    elif no_water_days >= 2:
        urgency = 2
    elif no_water_days >= 1:
        urgency = 1

    # Base bid tracks opponent yesterday top bid but underbids to steal at lower cost.
    # If opponent was very aggressive (high top_bid), we respond with enough to avoid losing water.
    aggressive_threshold = DAILY_SALARY * 0.85

    if top_bid >= aggressive_threshold:
        if urgency >= 3:
            target = min(budget, DAILY_SALARY * 0.95)
        elif urgency == 2:
            target = min(budget, DAILY_SALARY * 0.75)
        else:
            # Underbid slightly to exploit potential overspending by others.
            target = min(budget, max(0.0, top_bid * 0.88))
    else:
        if urgency >= 3:
            target = min(budget, DAILY_SALARY * 0.9)
        elif urgency == 2:
            target = min(budget, DAILY_SALARY * 0.65)
        else:
            # When not under immediate threat, bid moderately; scale down when supply is higher.
            mid = max(0.0, DAILY_SALARY * (0.5 + 0.15 * (1.0 - supply_scale)))
            # Also ensure we are not wildly above the market.
            target = min(budget, max(0.0, min(mid, top_bid * 0.9 + 5.0 if top_bid > 0 else mid)))

    # If budget is tiny, just bid what we can.
    if budget <= 1.0:
        return max(0.0, budget)

    # Final clamp to reasonable range.
    target = max(0.0, min(budget, float(target)))
    return target

def get_bid(day_context, my_status, opponents_status):
